@router.post("/api/routines")
def save_routine(body: Draft):
    from ask_soony import api

    with _lock:
        items = [r for r in _all() if r.get("id") != body.id]
        items.append(
            {
                **body.model_dump(),
                "enabled": True,
                "created_at": api.now().isoformat(),
                "runs": [],
                "seen": [],
            }
        )
